import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Remove near-duplicates based on correlation
    corr_pairs = [(a, b) for a, b in [
        ('HCPD11', 'DTRA3'), ('AIH4', 'DTRA3'), ('FOA2', 'DTRA3'),
        ('KDP19', 'JBB14B'), ('HCPD11', 'AIH4'), ('ETKG17P', 'DTRA3'),
        ('HCPD11', 'FOA2'), ('FOA2', 'AIH4'), ('PIW16', 'DTRA3'),
        ('HCPD11', 'ETKG17P'), ('JZV4', 'DTRA3'), ('WAT9L', 'DTRA3'),
        ('JZV4', 'AIH4'), ('CXV15', 'DTRA3'), ('AIH4', 'WAT9L'),
        ('FOA2', 'PIW16'), ('PUEY13', 'YKX6'), ('HCPD11', 'PIW16'),
        ('PIW16', 'AIH4'), ('YKX6', 'WAT9L')
    ] if a in feats.ids and b in feats.ids]

    # Build set of features to consider
    keep_ids = set(feats.ids)
    for a, b in corr_pairs:
        if a in keep_ids and b in keep_ids:
            # Remove one of each pair (keep the one with higher effect size)
            idx_a = feats.column(a)
            idx_b = feats.column(b)
            effect_a = np.mean(feats.x[feats.y==1, idx_a]) - np.mean(feats.x[feats.y==0, idx_a])
            effect_b = np.mean(feats.x[feats.y==1, idx_b]) - np.mean(feats.x[feats.y==0, idx_b])
            if abs(effect_a) >= abs(effect_b):
                keep_ids.remove(b)
            else:
                keep_ids.remove(a)

    # Select features based on t-test significance and effect size
    selected_features = []
    for fid in keep_ids:
        idx = feats.column(fid)
        if feats.types[idx] == 'clinical':
            # For clinical features, use Mann-Whitney U test
            x1 = feats.x[feats.y==1, idx]
            x0 = feats.x[feats.y==0, idx]
            try:
                stat, p = stats.mannwhitneyu(x1, x0, alternative='two-sided')
            except:
                continue
        else:
            # For other features, use Welch's t-test
            x1 = feats.x[feats.y==1, idx]
            x0 = feats.x[feats.y==0, idx]
            try:
                stat, p = stats.ttest_ind(x1, x0, equal_var=False)
            except:
                continue

        # Check if significant and has meaningful effect
        if p < 0.05 and abs(stat) > 2.0:
            effect_size = np.mean(x1) - np.mean(x0)
            selected_features.append((fid, effect_size, p))

    # Sort by absolute effect size
    selected_features.sort(key=lambda x: abs(x[1]), reverse=True)

    # If no significant features found, return empty design
    if not selected_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top features for drivers and columns (keep model small)
    drivers = [f[0] for f in selected_features[:3]]  # Limit to 3 drivers
    columns = [f[0] for f in selected_features[:5]]   # Limit to 5 columns

    # Check for interaction terms among top features
    products = []
    # Only add interactions between top 3 features to keep model small
    top_cols = columns[:3]
    for i in range(len(top_cols)):
        for j in range(i+1, len(top_cols)):
            if top_cols[i] != top_cols[j]:
                products.append((top_cols[i], top_cols[j]))

    # Create loadings for weighted score
    loadings = {}
    for fid, effect_size, p in selected_features[:len(columns)]:
        loadings[fid] = effect_size

    return Design(drivers=tuple(drivers), columns=tuple(columns), 
                  products=tuple(products), loadings=loadings)

